#include "mesh.h"#include "FileStuff.h"void zeroElevation ( FSSpec theMeshFSSpec );void zeroElevation ( FSSpec theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	Str255		theNewFileName = "\p:mesh.out:mesh";	Str255		theBackupFileName = "\p:mesh.old";	OSErr		theError;	char meshFolder[48] = ":mesh.out:";	int i, j, x, y;	long meshSize, meshWidth, meshHeight;	struct meshHeader theMeshHeader;	gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	for (y = 0, i = 0, j = 0; y < meshHeight; y++, j += meshWidth)		for (x = 0; x < meshWidth; x++, i++)				theGrid[i].height =0;	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );}